(()=>{const original=window.fetch.bind(window);window.fetch=(input,options)=>{const url=new URL(typeof input==='string'?input:input instanceof URL?input.href:input.url,location.href);if(url.origin===location.origin&&/^\/(experiment|fitting|journal|destinations)\//.test(url.pathname)){const status=url.pathname.endsWith('/status');return Promise.resolve(new Response(JSON.stringify({configured:false,available:false,message:'当前为静态展示，可使用上传、选衣和本机手账；AI功能需要已配置的后端。'}),{status:status?200:503,headers:{'Content-Type':'application/json'}}))}return original(input,options)}})();